Audit Queue.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Audit Queue container

Container_Boundary(audit_queue, "Audit Queue") {
    Component(Amazon_SQS_Standard_FIFO_Queue, "Amazon SQS Standard/FIFO Queue", "Amazon SQS", "Asynchronous message queue for decoupling scoring from storage and preventing latency.")
    Component(Dead_Letter_Queue_DLQ, "Dead Letter Queue (DLQ)", "Amazon SQS DLQ", "Captures and isolates failed audit messages for troubleshooting and analysis.")
}

Rel(Amazon_SQS_Standard_FIFO_Queue, Dead_Letter_Queue_DLQ, "Routes undeliverable messages")

@enduml

Audit Stream Processor.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(audit_stream_processor, "Audit Stream Processor") {
    Component(KinesisFirehoseDeliveryStream, "Kinesis Firehose Delivery Stream", "Amazon Kinesis Data Firehose", "Ingests raw decision payloads from the Audit Queue and buffers them for batch delivery.")
    Component(EncryptionManager, "Encryption Manager", "AWS KMS", "Encrypts audit data streams and payloads to ensure security and compliance.")
}

Rel(KinesisFirehoseDeliveryStream, EncryptionManager, "Applies encryption via", "")

@enduml

Audit Storage.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Audit Storage container

Component(AuditStreamProcessor, "Audit Stream Processor", "Amazon Kinesis Firehose", "Stream decision payloads")

Container_Boundary(AuditStorage, "Audit Storage") {
    Component(AmazonS3, "Amazon S3", "AWS S3", "Stores immutable audit records for 7-year tamper-evident retention.")
    Component(S3ObjectLock, "S3 Object Lock", "AWS S3 Object Lock (Compliance Mode)", "Enforces WORM-compliant tamper-evident retention policies.")
    Component(AWSKMS, "AWS KMS", "AWS Key Management Service", "Provides Customer Managed Keys (CMKs) for data at rest encryption.")
    Component(AWSVPCGatewayEndpoints, "AWS VPC Gateway Endpoints", "AWS VPC", "Ensures secure network isolation for data traffic.")
}

Rel(AuditStreamProcessor, AmazonS3, "Write immutable audit records", "HTTPS / S3 PutObject")

@enduml
